// VIRTUAL LOFT — one place to play sounds (all generated by audiogen/gen.py into
// Resources/Audio). Effects with a position play in 3D at that spot (you hear
// WHICH animal finished); UI sounds play 2D. Missing clips are silently skipped.

using System.Collections.Generic;
using UnityEngine;

public static class LoftAudio
{
    static readonly Dictionary<string, AudioClip> cache = new Dictionary<string, AudioClip>();
    static AudioSource ui;

    public static AudioClip Clip(string name)
    {
        if (!cache.TryGetValue(name, out var c))
        {
            c = Resources.Load<AudioClip>($"Audio/{name}");
            cache[name] = c; // remember misses too
        }
        return c;
    }

    // 3D sound at a world position (animals, teleport pads).
    public static void PlayAt(string name, Vector3 position, float volume = 1f)
    {
        if (!Application.isPlaying) return; // editor tools / LoftVerify: stay silent
        var c = Clip(name);
        if (c != null) AudioSource.PlayClipAtPoint(c, position, volume);
    }

    // 2D sound (buttons, approvals, party horn).
    public static void Play(string name, float volume = 1f)
    {
        if (!Application.isPlaying) return;
        var c = Clip(name);
        if (c == null) return;
        if (ui == null)
        {
            var go = new GameObject("LoftAudioUI");
            Object.DontDestroyOnLoad(go);
            ui = go.AddComponent<AudioSource>();
            ui.spatialBlend = 0f;
            ui.playOnAwake = false;
        }
        ui.PlayOneShot(c, volume);
    }
}
